mapper.select:
SELECT
    COUNT(*) AS totalUsageCount,
    COALESCE(SUM(
        CASE WHEN recommendation_type = 'LOAN' THEN 1 ELSE 0 END
    ), 0) AS loanUsageCount,
    COALESCE(SUM(
        CASE WHEN recommendation_type = 'INSURANCE' THEN 1 ELSE 0 END
    ), 0) AS insuranceUsageCount,
    COALESCE(SUM(
        CASE WHEN recommendation_type = 'ACCOUNT' THEN 1 ELSE 0 END
    ), 0) AS accountUsageCount,
    COALESCE(SUM(
        CASE WHEN outcome_type = 'PRODUCT_RESULT' THEN 1 ELSE 0 END
    ), 0) AS productResultCount,
    COALESCE(SUM(
        CASE WHEN outcome_type = 'CONSULTATION_REDIRECT' THEN 1 ELSE 0 END
    ), 0) AS consultationRedirectCount,
    MAX(created_at) AS latestUsedAt
FROM recommendation_usage_logs
WHERE created_at >= #{startedAt}
